```java
public class DoublyLinkedList {
    private Node head;
    private Node tail;

    // Node class definition
    private static class Node {
        int value;
        Node prev;
        Node next;

        Node(int value) {
            this.value = value;
            this.prev = null;
            this.next = null;
        }
    }

    // Method to reverse the order of the elements in the list
    public void reverse() {
        if (head == null || head.next == null) {
            return;
        }

        Node current = head;
        Node temp = null;

        while (current != null) {
            temp = current.prev;
            current.prev = current.next;
            current.next = temp;
            current = current.prev;
        }

        if (temp != null) {
            head = temp.prev;
        }
    }
}
```

