            }
        }

        double sum = calculateSum(rows - 1, columns - 1);
        System.out.println("Sum of all elements in the matrix: " + sum);
    }

    private static double calculateSum(int row, int column) {
        if (row < 0 || column < 0) {
            return 0;
        }

        if (memo[row][column] != 0) {
            return memo[row][column];
        }

        double sum = matrix[row][column] + calculateSum(row - 1, column) + calculateSum(row, column - 1) - calculateSum(row - 1, column - 1);
