#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <cmath>

std::mutex mtx;
std::vector<std::pair<int, int>> primePairs;

bool isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

void findPrimePairs(int start, int end, int target) {
    for (int i = start; i <= end; i++) {
        int complement = target - i;
        if (isPrime(i) && isPrime(complement)) {
            std::lock_guard<std::mutex> lock(mtx);
            primePairs.push_back(std::make_pair(i, complement));
            std::cout << "Thread ID: " << std::this_thread::get_id() << " - Found pair: " << i << " + " << complement << std::endl;
        }
    }
}

int main() {
    int targetSum;
    std::cout << "Enter the target sum (1 to 1000): ";
    std::cin >> targetSum;

    if (targetSum < 1 || targetSum > 1000) {
        std::cout << "Invalid input. Target sum must be between 1 and 1000." << std::endl;
        return 0;
    }

    int numThreads = std::thread::hardware_concurrency();
    int workload = targetSum / numThreads;
    std::vector<std::thread> threads;

    for (int i = 0; i < numThreads; i++) {
        int start = i * workload + 1;
        int end = (i == numThreads - 1) ? targetSum : (i + 1) * workload;
        threads.push_back(std::thread(findPrimePairs, start, end, targetSum));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
