To implement a custom data structure that supports insertion, deletion, and search operations with a time complexity of O(log n), we can use a balanced binary search tree (BBST). A BBST is a tree-based data structure where the height of the tree is always balanced, ensuring efficient operations.

We can use a self-balancing binary search tree such as AVL tree or Red-Black tree to achieve the desired time complexity. In this case, we'll use the AVL tree.

Here is a possible implementation of the custom data structure:

```python
class CustomDataStructure:
    def __init__(self):
        self.root = None

    def insert(self, string):
        self.root = self._insert_helper(self.root, string)

    def _insert_helper(self, node, string):
        if node is None:
            return Node(string)

        if string < node.value:
            node.left = self._insert_helper(node.left, string)
        elif string > node.value:
            node.right = self._insert_helper(node.right, string)

        node.height = 1 + max(self._get_height(node.left), self._get_height(node.right))
        balance = self._get_balance(node)

        # Left Left Case
        if balance > 1 and string < node.left.value:
            return self._rotate_right(node)

        # Right Right Case
        if balance < -1 and string > node.right.value:
            return self._rotate_left(node)

        # Left Right Case
        if balance > 1 and string > node.left.value:
            node.left = self._rotate_left(node.left)
            return self._rotate_right(node)

        # Right Left Case
        if balance < -1 and string < node.right.value:
            node.right = self._rotate_right(node.right)
            return self._rotate_left(node)

        return node

    def delete(self, string):
        self.root = self._delete_helper(self.root, string)

    def _delete_helper(self, node, string):
        if node is None:
            return node

        if string < node.value:
            node.left = self._delete_helper(node.left, string)
        elif string > node.value:
            node.right = self._delete_helper(node.right, string)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            else:
                temp = self._get_min_value_node(node.right)
                node.value = temp.value
                node.right = self._delete_helper(node.right, temp.value)

        node.height = 1 + max(self._get_height(node.left), self._get_height(node.right))
        balance = self._get_balance(node)

        # Left Left Case
        if balance > 1 and self._get_balance(node.left) >= 0:
            return self._rotate_right(node)

        # Right Right Case
        if balance < -1 and self._get_balance(node.right) <= 0:
            return self._rotate_left(node)

        # Left Right Case
        if balance > 1 and self._get_balance(node.left) < 0:
            node.left = self._rotate_left(node.left)
            return self._rotate_right(node)

        # Right Left Case
        if balance < -1 and self._get_balance(node.right) > 0:
            node.right = self._rotate_right(node.right)
            return self._rotate_left(node)

        return node

    def search(self, string):
        return self._search_helper(self.root, string)

    def _search_helper(self, node, string):
        if node is None or node.value == string:
            return node

        if string < node.value:
            return self._search_helper(node.left, string)
        else:
            return self._search_helper(node.right, string)

    def _get_height(self, node):
        if node is None:
            return 0
        return node.height

    def _get_balance(self, node):
        if node is None:
            return 0
        return self._get_height(node.left) - self._get_height(node.right)

    def _rotate_left(self, z):
        y = z.right
        T2 = y.left

        y.left = z
        z.right = T2

        z.height = 1 + max(self._get_height(z.left), self._get_height(z.right))
        y.height = 1 + max(self._get_height(y.left), self._get_height(y.right))

        return y

    def _rotate_right(self, z):
        y = z.left
        T3 = y.right

        y.right = z
        z.left = T3

        z.height = 1 + max(self._get_height(z.left), self._get_height(z.right))
        y.height = 1 + max(self._get_height(y.left), self._get_height(y.right))

        return y

    def _get_min_value_node(self, node):
        if node is None or node.left is None:
            return node
        return self._get_min_value_node(node.left)

