            return false;
        }

        if (calculateWeightedGPA() < minGpa) {
            return false;
        }

        for (Course course : courses) {
            for (Course prerequisite : course.getPrerequisites()) {
                if (!courses.contains(prerequisite)) {
                    return false;
                }
            }
        }

        return true;
    }

