Here is an example C++ program that implements a Stack data structure using linked lists:

```cpp
#include <iostream>

using namespace std;

struct Node {
    int data;
    Node* next;
};

class Stack {
private:
    Node* top;
    int count;

public:
    Stack() {
        top = nullptr;
        count = 0;
    }

    void push(int value) {
        Node* newNode = new Node;
        newNode->data = value;
        newNode->next = top;
        top = newNode;
        count++;
    }

    int pop() {
        if (isEmpty()) {
            cout << "Stack is empty." << endl;
            return -1;
        }
        Node* temp = top;
        int poppedValue = temp->data;
        top = top->next;
        delete temp;
        count--;
        return poppedValue;
    }

    int peek() {
        if (isEmpty()) {
            cout << "Stack is empty." << endl;
            return -1;
        }
        return top->data;
    }

    bool isEmpty() {
        return top == nullptr;
    }

    void print() {
        if (isEmpty()) {
            cout << "Stack is empty." << endl;
            return;
        }
        Node* temp = top;
        while (temp != nullptr) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }

    int size() {
        return count;
    }

    void clear() {
        while (!isEmpty()) {
            pop();
        }
    }

    int search(int value) {
        if (isEmpty()) {
            return -1;
        }
        Node* temp = top;
        int index = 0;
        while (temp != nullptr) {
            if (temp->data == value) {
                return index;
            }
            temp = temp->next;
            index++;
        }
        return -1;
    }

    Stack copy() {
        Stack newStack;
        Node* temp = top;
        while (temp != nullptr) {
            newStack.push(temp->data);
            temp = temp->next;
        }
        return newStack;
    }
};

int main() {
    Stack stack;

    // Push elements to the stack
    stack.push(10);
    stack.push(20);
    stack.push(30);
    stack.push(40);

    // Print all elements in the stack
    cout << "Stack elements: ";
    stack.print();

    // Pop an element from the stack
    int poppedValue = stack.pop();
    cout << "Popped element: " << poppedValue << endl;

    // Peek at the top element
    int topElement = stack.peek();
    cout << "Top element: " << topElement << endl;

    // Check if stack is empty
    bool empty = stack.isEmpty();
    cout << "Is stack empty? " << (empty ? "Yes" : "No") << endl;

    // Get the size of the stack
    int stackSize = stack.size();
    cout << "Stack size: " << stackSize << endl;

    // Search for an element in the stack
    int searchIndex = stack.search(20);
    if (searchIndex != -1) {
        cout << "Element found at index: " << searchIndex << endl;
    } else {
        cout << "Element not found in the stack." << endl;
    }

    // Copy the stack
    Stack copiedStack = stack.copy();
    cout << "Copied stack elements: ";
    copiedStack.print();

    // Clear the stack
    stack.clear();
    cout << "Stack elements after clear: ";
    stack.print();

    return 0;
}
```

