```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_WORDS 1000

// Structure to store word and its frequency
struct WordFrequency {
    char word[50];
    int frequency;
};

// Function to remove punctuation marks from a word
void removePunctuation(char *word) {
    int len = strlen(word);
    int i, j;
    for (i = 0, j = 0; i < len; i++) {
        if (!ispunct(word[i])) {
            word[j++] = tolower(word[i]);
        }
    }
    word[j] = '\0';
}

// Function to check if a word is already present in the frequency array
int isWordPresent(struct WordFrequency *freqArray, int count, char *word) {
    for (int i = 0; i < count; i++) {
        if (strcmp(freqArray[i].word, word) == 0) {
            return i;
        }
    }
    return -1;
}

// Function to compare two WordFrequency structs for qsort
int compare(const void *a, const void *b) {
    struct WordFrequency *word1 = (struct WordFrequency *)a;
    struct WordFrequency *word2 = (struct WordFrequency *)b;
    return (word2->frequency - word1->frequency);
}

int main() {
    char paragraph[1000];
    char *token;
    struct WordFrequency freqArray[MAX_WORDS];
    int count = 0;

    // Prompt user for input paragraph
    printf("Enter a paragraph:\n");
    fgets(paragraph, sizeof(paragraph), stdin);

    // Tokenize paragraph into words
    token = strtok(paragraph, " .,!?");

    while (token != NULL) {
        removePunctuation(token);

        // Check if word is already present in frequency array
        int index = isWordPresent(freqArray, count, token);
        if (index != -1) {
            freqArray[index].frequency++;
        } else {
            // Add new word to frequency array
            strcpy(freqArray[count].word, token);
            freqArray[count].frequency = 1;
            count++;
        }

        token = strtok(NULL, " .,!?");  // Get next word
    }

    // Sort the frequency array in descending order
    qsort(freqArray, count, sizeof(struct WordFrequency), compare);

    // Print the result
    printf("Unique Words\tFrequency\n");
    for (int i = 0; i < count; i++) {
        printf("%s\t\t%d\n", freqArray[i].word, freqArray[i].frequency);
    }

    return 0;
}
```

In this program, we use the `strtok` function to tokenize the paragraph into words, considering spaces and punctuation marks as delimiters. Each word is then processed to remove punctuation marks and converted to lowercase using the `removePunctuation` function. We use the `isWordPresent` function to check if a word is already present in the `freqArray` of `WordFrequency` structs. If it is present, we increment its frequency. Otherwise, we add the word to the `freqArray` with a frequency of 1. After processing all the words, we use the `qsort` function to sort the `freqArray` in descending order based on the frequency of each word occurrence. Finally, we print the result in a tabular format with the unique words and their frequencies.

