class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class Stack:
    def __init__(self):
        self.root = None
        self.max_node = None

    def push(self, value):
        if self.root is None:
            self.root = Node(value)
            self.max_node = self.root
        else:
            new_node = Node(value)
            if value > self.max_node.value:
                new_node.left = self.max_node
                self.max_node = new_node
            else:
                current = self.root
                while True:
                    if value > current.value:
                        if current.right is None:
                            current.right = new_node
                            break
                        else:
                            current = current.right
                    else:
                        if current.left is None:
                            current.left = new_node
                            break
                        else:
                            current = current.left

    def pop(self):
        if self.root is None:
            return None

        if self.root == self.max_node:
            self.max_node = self.max_node.left

        current = self.root
        parent = None
        while current.right is not None:
            parent = current
            current = current.right

        if parent is None:
            self.root = current.left
        else:
            parent.right = current.left

        return current.value

    def peek(self):
        if self.root is None:
            return None

        current = self.root
        while current.right is not None:
            current = current.right

        return current.value

    def get_max(self):
        if self.max_node is None:
            return None

        return self.max_node.value

