public class ArrayPrinter {
    public static void printElements(int[] arr) {
        // Check if the array contains at least 5 elements
        if (arr.length < 5) {
            System.out.println("Array must contain at least 5 elements.");
            return;
        }

        // Sort the array in ascending order
        Arrays.sort(arr);

        // Remove duplicates from the array
        int[] uniqueArr = removeDuplicates(arr);

        // Sort the unique array in descending order
        Arrays.sort(uniqueArr);

        // Print elements greater than 2 and even numbers
        for (int i = 0; i < uniqueArr.length; i++) {
            if (uniqueArr[i] > 2 && uniqueArr[i] % 2 == 0) {
                System.out.print(uniqueArr[i] + " ");
            }
        }

        System.out.println();
    }

    private static int[] removeDuplicates(int[] arr) {
        int n = arr.length;
        if (n == 0 || n == 1) {
            return arr;
        }

        int[] temp = new int[n];
        int j = 0;

        for (int i = 0; i < n - 1; i++) {
            if (arr[i] != arr[i + 1]) {
                temp[j++] = arr[i];
            }
        }

        temp[j++] = arr[n - 1];

        int[] uniqueArr = new int[j];
        System.arraycopy(temp, 0, uniqueArr, 0, j);

        return uniqueArr;
    }

    public static void main(String[] args) {
        int[] arr = {1, 3, 4, 2, 6, 5, 4, 3, 7, 8, 9};
        printElements(arr);
    }
